import { tv, type VariantProps } from "@/lib/beton/tv";

export const testimonial = tv({
  slots: {
    root: "flex h-full flex-col gap-5 border-3 border-border bg-raised p-6 shadow-sm",
    mark: "font-display text-h1 leading-none font-black text-foreground select-none",
    quote: "text-pretty text-foreground",
    footer: "mt-auto flex items-center gap-3 border-t-3 border-border pt-4",
    person: "flex min-w-0 flex-col",
    name: "font-display font-extrabold text-foreground",
    role: "font-mono text-xs font-bold",
    list: "grid gap-6",
  },
  variants: {
    size: {
      sm: { quote: "text-base" },
      md: { quote: "text-lg" },
      lg: { quote: "text-xl" },
    },
    columns: {
      1: { list: "max-w-2xl" },
      2: { list: "sm:grid-cols-2" },
      3: { list: "sm:grid-cols-2 lg:grid-cols-3" },
    },
  },
  defaultVariants: {
    size: "md",
    columns: 3,
  },
});

export type TestimonialVariants = VariantProps<typeof testimonial>;

import { testimonial, type TestimonialVariants } from "@/lib/beton/recipes/testimonial.recipe";
import type { ReactNode } from "react";
import { Section, type SectionProps } from "@/components/ui/beton/section";

export interface Quote {
  /** What they said. */
  quote: ReactNode;
  /** Who said it. */
  name: ReactNode;
  /** What they do, and where. */
  role?: ReactNode;
  /** A picture or an avatar. */
  portrait?: ReactNode;
}

export interface TestimonialProps extends Omit<SectionProps, "children">, TestimonialVariants {
  /** The quotes, in order. */
  quotes: Quote[];
  /** Classes for the grid itself. */
  listClassName?: string;
}

/** What people say, attributed to the people who said it. */
export function Testimonial({
  quotes,
  size = "md",
  columns = 3,
  listClassName,
  ...props
}: TestimonialProps) {
  const styles = testimonial({ size, columns });
  return (
    <Section {...props}>
      <ul className={styles.list({ class: listClassName })}>
        {quotes.map((entry, index) => (
          <li key={index}>
            <figure className={styles.root()}>
              <span aria-hidden="true" className={styles.mark()}>
                &ldquo;
              </span>
              <blockquote className={styles.quote()}>{entry.quote}</blockquote>
              <figcaption className={styles.footer()}>
                {entry.portrait}
                <span className={styles.person()}>
                  <span className={styles.name()}>{entry.name}</span>
                  {entry.role ? <span className={styles.role()}>{entry.role}</span> : null}
                </span>
              </figcaption>
            </figure>
          </li>
        ))}
      </ul>
    </Section>
  );
}
